 public static JavaScriptSerializer Json = new JavaScriptSerializer {MaxJsonLength=4000000};
 public static void StartNewStory(Save s,string chapter){s.tavernBattle=null;if(s.rogue==null)s.rogue=new RogueProfile();s.rogue.Normalize();s.rogue.preparations.Clear();s.rogue.preparationRuns.Clear();s.rogue.prepSession=null;s.rogue.prepChapter=null;s.rogue.preparationActive=false;if(s.rogue.run!=null&&!String.IsNullOrEmpty(s.rogue.run.vocabularyChapter))s.rogue.run=null;StoryRoutes.Normalize(s);s.storyFlags.Clear();s.storyRoutes.Clear();s.xp=0;s.sectionAttempts.Clear();s.sectionStars.Clear();s.answerStarted.Clear();s.answerTimely.Clear();s.heardLines.Clear();s.quizAnswers.Clear();s.positions.Clear();s.completed.Clear();s.trust.Clear();s.decisions.Clear();s.rewardedDecisions.Clear();s.hasGame=true;s.lastChapter=chapter;s.positions[chapter]=0;}
 public static int Level(int xp) {return 1+xp/100;}
 public static int Review(Word w,bool known,DateTime now) {int[] gaps={0,1,3,7,14,30};w.box=known?Math.Min(5,w.box+1):0;w.due=now.Date.AddDays(gaps[w.box]).ToString("yyyy-MM-dd");string today=now.ToString("yyyy-MM-dd");int reward=known && w.lastReward!=today?10:0;if(reward>0)w.lastReward=today;return reward;}
 public static bool Due(Word w,DateTime now){DateTime d;return !DateTime.TryParse(w.due,out d)||d.Date<=now.Date;}
 public static string Key(string chapter,int line){return chapter+":"+line;}
 public static void Validate(Chapter c,string folder) {
  if(c==null||String.IsNullOrWhiteSpace(c.id)||String.IsNullOrWhiteSpace(c.title)||c.lines==null||c.lines.Count==0||c.lines.Count>1000)throw new Exception("章节须包含 id、title 和 1–1000 句 lines。");
  foreach(var l in c.lines)if(l==null||String.IsNullOrWhiteSpace(l.text)||l.text.Length>1200)throw new Exception("每句 text 必须非空，且不超过 1200 字符。");
  foreach(var l in c.lines){if(!String.IsNullOrWhiteSpace(l.scene)&&(!File.Exists(SafePath(folder,l.scene))||l.sceneCell<0||l.sceneCell>5))throw new Exception("剧情场景图片或场景索引无效。");if(l.pose.HasValue&&(l.pose.Value<0||l.pose.Value>2))throw new Exception("角色神态索引无效。");}
  if(!String.IsNullOrWhiteSpace(c.audio)) {double previous=0;foreach(var l in c.lines){if(Double.IsNaN(l.start)||Double.IsNaN(l.end)||Double.IsInfinity(l.start)||Double.IsInfinity(l.end)||l.start<previous||l.end<=l.start)throw new Exception("音频章节的 start/end 须为按顺序排列、不重叠的有效秒数。");previous=l.end;}if(!File.Exists(SafePath(folder,c.audio)))throw new Exception("找不到章节音频文件。");}
  if(!String.IsNullOrWhiteSpace(c.background)&&!File.Exists(SafePath(folder,c.background)))throw new Exception("找不到章节背景图片。");
  if(c.questions!=null&&(c.questions.Count>50||c.questions.Any(q=>q==null||String.IsNullOrWhiteSpace(q.prompt)||q.options==null||q.options.Count!=4||q.options.Any(o=>String.IsNullOrWhiteSpace(o))||q.answer<0||q.answer>3)))throw new Exception("章节题目需有题干、四个选项及 0–3 的正确答案索引。");
  if(c.inlineQuestions&&!TavernStory.Is(c)&&(c.questions==null||(c.questions.Count<3||c.questions.Count>4)||c.questions.Any(q=>q.afterLine<0||q.afterLine>=c.lines.Count)||c.questions.Select(q=>q.afterLine).Distinct().Count()!=c.questions.Count||c.questions.Max(q=>q.afterLine)!=c.lines.Count-1))throw new Exception("分段题需有三或四个不同的有效台词位置，并在最后一句设置一道题。");
  if(c.actors!=null)foreach(var actor in c.actors) {if(actor==null||String.IsNullOrWhiteSpace(actor.id)||String.IsNullOrWhiteSpace(actor.image)||!File.Exists(SafePath(folder,actor.image)))throw new Exception("角色立绘配置无效。");}
  if(c.decisions!=null)foreach(var d in c.decisions)if(d.afterLine<0||d.afterLine>=c.lines.Count||d.options==null||d.options.Count<2||d.options.Count>4||d.options.Any(o=>o==null||String.IsNullOrWhiteSpace(o.text)||Math.Abs(o.trust)>10))throw new Exception("剧情选择需有有效句号和 2–4 个选项，trust 范围为 -10 至 10。");
 }
 public static string SafePath(string folder,string value){if(Path.IsPathRooted(value))throw new Exception("章节资源请使用相对路径。");string root=Path.GetFullPath(folder).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;string path=Path.GetFullPath(Path.Combine(root,value));if(!path.StartsWith(root,StringComparison.OrdinalIgnoreCase))throw new Exception("资源路径不能离开章节文件夹。");return path;}
}
public class LexEntry {public string Meaning;public string Phonetic;}
public class Lexicon {
 public Dictionary<string,LexEntry> Entries=new Dictionary<string,LexEntry>(StringComparer.OrdinalIgnoreCase);
 public static Lexicon Load(string path){var lex=new Lexicon();if(!File.Exists(path))return lex;using(var raw=File.OpenRead(path))using(var gz=new GZipStream(raw,CompressionMode.Decompress))using(var reader=new StreamReader(gz,Encoding.UTF8)){string row;while((row=reader.ReadLine())!=null){var cells=row.Split(new[]{'\t'},3);if(cells.Length==3)lex.Entries[cells[0]]=new LexEntry{Phonetic=cells[1],Meaning=cells[2]};}}return lex;}
 public LexEntry Find(string word){LexEntry result;return Entries.TryGetValue(word,out result)?result:null;}
}
