 void RenderScene(Graphics g){g.InterpolationMode=PixelArt?InterpolationMode.NearestNeighbor:InterpolationMode.HighQualityBicubic;g.PixelOffsetMode=PixelArt?PixelOffsetMode.Half:PixelOffsetMode.Default;DrawSceneBackdrop(g);if(WaystationPortraits)DrawWaystationPortraits(g);foreach(var a in Actors.Where(a=>a.Visible&&!WaystationPortraits).OrderBy(a=>a.Emphasis)){float k=a.Emphasis;float scene=Math.Max(180,Height);float h=PixelArt?Math.Max(150,Height-60)*(0.95f+0.05f*k):(scene+30)*(.80f+.20f*k);float w=h*a.Image.Width/a.Image.Height;float center=PixelArt?(a.Side=="right"?Width*.74f:Width*.26f):(a.Side=="right"?Width*(.84f-.14f*k):Width*(.16f+.14f*k));float y=PixelArt?14:14+42*(1-k);float brightness=.60f+.40f*k;float opacity=1f;using(var attr=new ImageAttributes()){var matrix=new ColorMatrix(new float[][]{new[]{brightness,0f,0f,0f,0f},new[]{0f,brightness,0f,0f,0f},new[]{0f,0f,brightness,0f,0f},new[]{0f,0f,0f,opacity,0f},new[]{0f,0f,0f,0f,1f}});attr.SetColorMatrix(matrix);g.DrawImage(a.Image,new Rectangle((int)(center-w/2),(int)y,(int)w,(int)h),0,0,a.Image.Width,a.Image.Height,GraphicsUnit.Pixel,attr);}}if(Novel&&PixelArt){using(var b=new SolidBrush(Color.FromArgb(220,15,18,35)))g.FillRectangle(b,0,Height-DialogHeight-52,Width,DialogHeight);using(var b=new SolidBrush(Color.FromArgb(245,12,15,29)))g.FillRectangle(b,0,Height-52,Width,52);using(var p=new Pen(Color.FromArgb(115,160,134,235),2)){g.DrawLine(p,0,Height-DialogHeight-52,Width,Height-DialogHeight-52);g.DrawLine(p,0,Height-52,Width,Height-52);}}else if(Novel){var fade=new Rectangle(0,Math.Max(0,Height-300),Width,Math.Min(300,Height));using(var gradient=new LinearGradientBrush(fade,Color.FromArgb(0,42,17,36),Color.FromArgb(185,42,17,36),90))g.FillRectangle(gradient,fade);using(var strip=new SolidBrush(Color.FromArgb(120,36,15,29)))g.FillRectangle(strip,0,Height-52,Width,52);using(var edge=new Pen(Color.FromArgb(70,255,224,196)))g.DrawLine(edge,16,Height-52,Width-16,Height-52);}
 }
