 void ShowStory(){TavernStory.Migrate(save);ClearPage();page="story";if(current==null){ShowMain();return;}if(!developerMode&&!SectionRules.Unlocked(current,chapters,save)){SetStatus("上一节至少达到两星才能进入。");ShowChapters();return;}if(!developerMode&&TavernStory.Is(current)&&!save.storyFlags.Contains(TavernStory.OpeningFlag)){ShowTavernOpening();return;}if(!developerMode&&TryTavernTransition())return;if(!developerMode&&!TavernStory.Is(current)&&save.openingCgPending){ShowOpeningCg(true);return;}if(!developerMode&&TryStoryIntro())return;if(!developerMode&&!PreparationReady(current)){ShowPreparationHome();return;}if(!developerMode&&current.id=="neon-01-01"&&Attempt().started==0&&!Attempt().rulesShown){ShowEmbeddedRules();return;}if(!developerMode&&StoryRoutes.Enhanced(current.id)&&!Attempt().review&&Attempt().finished>0&&current.questions.All(q=>save.quizAnswers.ContainsKey(InlineKey(q)))){CompleteNeon();return;}LoadStage(current,true);stage.Novel=true;BuildNeonHud();stage.MouseUp+=StoryMouseUp;voiceStatus=Lab("",9,Muted);positionLabel=Lab("",9,Muted);
 var bar=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=52,BackColor=Color.Transparent,WrapContents=false,Padding=new Padding(0),Margin=new Padding(0)};stage.Controls.Add(bar);bar.Controls.Add(Mini("","home","返回主界面",ShowMain));bar.Controls.Add(Mini("","book","选择章节",()=>{if(TavernStory.Is(current))ShowTavernHub();else ShowChapters();}));bar.Controls.Add(Mini("","prev","前一句",Previous));playButton=Mini("","play","播放 / 暂停当前台词",TogglePlay);bar.Controls.Add(playButton);bar.Controls.Add(Mini("","next","下一句（可直接跳过）/ 选择回应",NextAndPlay));bar.Controls.Add(Mini("","auto","从当前句连续播放",PlayAll));bar.Controls.Add(Mini("","stop","停止播放",StopAudio));translationButton=Mini("中：开","","显示 / 隐藏中文",()=>{translating=!translating;save.chinese=translating;UpdateLine();});translationButton.Width=100;bar.Controls.Add(translationButton);englishButton=Mini("英：开","","显示 / 隐藏英文",()=>{englishVisible=!englishVisible;save.english=englishVisible;UpdateLine();});englishButton.Width=100;bar.Controls.Add(englishButton);bar.Controls.Add(Mini("","log","对话记录",History));AddSpeedControl(bar);bar.AutoScroll=false;int total=bar.Controls.Cast<Control>().Sum(c=>c.Width+c.Margin.Horizontal);Action align=()=>bar.Padding=new Padding(Math.Max(8,(bar.Width-total)/2),0,0,0);bar.Resize+=(sender,e)=>align();align();
 var dialog=new TableLayoutPanel{Dock=DockStyle.Bottom,Height=205,BackColor=Color.Transparent,Padding=new Padding(0,6,0,0),ColumnCount=1,RowCount=3,Margin=new Padding(0)};dialog.RowStyles.Add(new RowStyle(SizeType.Absolute,38));dialog.RowStyles.Add(new RowStyle(SizeType.Percent,100));dialog.RowStyles.Add(new RowStyle(SizeType.Absolute,55));stage.Controls.Add(dialog);dialogue=dialog;dialog.MouseUp+=StoryMouseUp;dialog.BringToFront();Action inset=()=>dialog.Padding=new Padding(Math.Max(32,stage.Width/9),6,Math.Max(32,stage.Width/9),0);stage.Resize+=(sender,e)=>{inset();RefreshDialogueSize();};inset();speakerLabel=new OutlinedLabel{PixelText=current.pixelArt,Dock=DockStyle.Fill,Font=GameTheme.Body(16,FontStyle.Bold),ForeColor=Color.FromArgb(255,230,205),Margin=new Padding(0)};speakerLabel.MouseUp+=StoryMouseUp;dialog.Controls.Add(speakerLabel,0,0);englishText=new SentenceView{Dock=DockStyle.Fill,BackColor=Color.Transparent,ForeColor=Color.White,Font=GameTheme.Latin(18),Margin=new Padding(0),Shadow=true};englishText.BlankClicked=()=>AdvanceStory();englishText.WordClicked=word=>AddWord(Normalize(word),current.lines[index].text);dialog.Controls.Add(englishText,0,1);translationLabel=new OutlinedLabel{PixelText=current.pixelArt,Dock=DockStyle.Fill,Font=GameTheme.Body(17),ForeColor=Color.White,Margin=new Padding(0)};translationLabel.MouseUp+=StoryMouseUp;dialog.Controls.Add(translationLabel,0,2);UpdateLine();stage.Invalidate();}
 void StoryMouseUp(object sender,MouseEventArgs e){if(e.Button==MouseButtons.Left)AdvanceStory();}
 void AdvanceStory(){if(page!="story"||pausedAudio||originalPlaying||(speech!=null&&speech.State!=SynthesizerState.Ready))return;int previous=index;Next();if(page=="story"&&index!=previous&&!allPlaying&&!originalPlaying)PlayCurrent();}
 void RefreshDialogueSize(){
  if(dialogue==null||dialogue.IsDisposed||englishText==null||englishText.IsDisposed)return;
  float scale=Math.Max(.72f,Math.Min(1.25f,Math.Min(stage.Width/1280f,stage.Height/740f)));
  float enSize=18*scale;
  if(Math.Abs(englishText.Font.Size-enSize)>.1f){var old=englishText.Font;englishText.Font=GameTheme.Latin(enSize);old.Dispose();var oldSpeaker=speakerLabel.Font;var oldTranslation=translationLabel.Font;speakerLabel.Font=GameTheme.Body(16*scale,FontStyle.Bold);translationLabel.Font=GameTheme.Body(17*scale);oldSpeaker.Dispose();oldTranslation.Dispose();}
  int width=Math.Max(30,dialogue.Width-dialogue.Padding.Horizontal);
  int lines=englishText.WrappedLineCount(Math.Max(30,width-22));
  int height=englishText.Visible?lines*(int)Math.Ceiling(englishText.Font.Height*1.55)+20:0;
  int chinese=String.IsNullOrEmpty(translationLabel.Text)?0:TextRenderer.MeasureText(translationLabel.Text,translationLabel.Font,new Size(Math.Max(30,width-5),int.MaxValue),TextFormatFlags.WordBreak|TextFormatFlags.NoPadding).Height+16;
  int speaker=(int)Math.Ceiling(speakerLabel.Font.Height*1.5)+8;
  int total=dialogue.Padding.Vertical+speaker+height+chinese;
  dialogue.SuspendLayout();dialogue.RowStyles[0].Height=speaker;dialogue.RowStyles[1].SizeType=SizeType.Absolute;dialogue.RowStyles[1].Height=height;dialogue.RowStyles[2].Height=chinese;dialogue.Height=total;dialogue.ResumeLayout();
  if(stage.PixelArt&&stage.DialogHeight!=total){stage.DialogHeight=total;stage.Snap();}
 }
 void TogglePlay(){
 if(pausedAudio){int err=0;if(originalPlaying){err=mciSendString("resume storyaudio",null,0,IntPtr.Zero);if(err!=0)err=mciSendString("play storyaudio",null,0,IntPtr.Zero);if(err==0)audioTimer.Start();}else if(speech!=null)speech.Resume();if(err!=0){SetStatus("无法继续音频，请点击停止后重新播放。");return;}pausedAudio=false;playButton.Icon="pause";playButton.Invalidate();return;}
 if(originalPlaying){int err=mciSendString("pause storyaudio",null,0,IntPtr.Zero);if(err!=0){SetStatus("音频暂停失败。");return;}audioTimer.Stop();pausedAudio=true;playButton.Icon="play";playButton.Invalidate();return;}
 if(speech!=null&&activePrompt!=null&&speech.State==SynthesizerState.Speaking){speech.Pause();pausedAudio=true;playButton.Icon="play";playButton.Invalidate();return;}
 PlayCurrent();}
 void SelectActorVoice(Line line){if(speech==null)return;var actor=current.actors==null?null:current.actors.FirstOrDefault(x=>x.id==line.actor);var voices=speech.GetInstalledVoices().Where(x=>x.Enabled&&x.VoiceInfo.Culture.TwoLetterISOLanguageName=="en").ToList();var gender=actor!=null&&actor.gender=="female"?VoiceGender.Female:actor!=null&&actor.gender=="male"?VoiceGender.Male:line.actor=="emma"?VoiceGender.Female:VoiceGender.Male;var chosen=actor!=null&&!String.IsNullOrWhiteSpace(actor.voice)?voices.FirstOrDefault(x=>x.VoiceInfo.Name==actor.voice):null;chosen=chosen??voices.FirstOrDefault(x=>x.VoiceInfo.Gender==gender);if(chosen!=null)speech.SelectVoice(chosen.VoiceInfo.Name);}
 void PrepareAudio(){string desired=String.IsNullOrWhiteSpace(current.audio)?"":StoryAudioFile();if(audioReady&&audioPath==desired)return;mciSendString("close storyaudio",null,0,IntPtr.Zero);audioReady=false;audioPath="";if(!String.IsNullOrWhiteSpace(current.audio)){try{audioPath=StoryAudioFile();int e=mciSendString("open \""+AudioDevicePath.Relative(audioPath)+"\" type waveaudio alias storyaudio",null,0,IntPtr.Zero);if(e!=0){var b=new StringBuilder(256);mciGetErrorString(e,b,256);SetStatus("原音无法打开："+b);audioPath="";}else {mciSendString("set storyaudio time format milliseconds",null,0,IntPtr.Zero);audioReady=true;}}catch{audioPath="";}}voiceStatus.Text=audioPath!=""?(String.IsNullOrWhiteSpace(current.audioLabel)?"导入章节音频":current.audioLabel):speech!=null?"Windows 英文合成音 · 非考试原音":"未安装英文语音：可导入音频章节";}
 void UpdateLine(){if(page!="story"||current==null)return;var l=current.lines[index];UpdateStoryVisual(l);speakerLabel.Text="【"+(String.IsNullOrWhiteSpace(l.speaker)?"旁白":l.speaker)+"】";bool subtitles=SubtitleAllowed();englishText.Text=subtitles?l.text:"";englishText.Marked=new HashSet<string>(save.words.Select(w=>w.text),StringComparer.OrdinalIgnoreCase);englishText.Invalidate();englishText.Visible=englishVisible&&subtitles;englishButton.Text=subtitles?(englishVisible?"英：开":"英：关"):"禁";translationButton.Text=ChineseAllowed()?(translating?"中：开":"中：关"):"禁";translationLabel.Text=translating&&subtitles&&ChineseAllowed()?l.translation:"";RefreshDialogueSize();stage.SetActor(l.actor);int t=save.trust.ContainsKey(current.id)?save.trust[current.id]:0;positionLabel.Text="合作信任 "+t+"  ·  "+(save.completed.Contains(current.id)?"已通关 · 重玩不会重复获得通关经验":"完成章节 +60 XP；首次剧情选择 +20 XP");save.positions[current.id]=index;save.lastChapter=current.id;save.hasGame=true;Persist();UpdateNeonHud();}
 static string Normalize(string s){return s.Trim().Trim('"','\'','.',',','!','?',':',';','(',')','[',']','—','“','”').ToLowerInvariant();}
 Decision Pending(){if(current.decisions==null)return null;return current.decisions.FirstOrDefault(d=>d.afterLine==index&&!save.decisions.Contains(Engine.Key(current.id,index)));}
 void Next(){RefreshListeningProgress();if(TryTavernBattle())return;StopAudio();if(!ResolveInlineQuestion())return;ClearAnsweredReplay();var d=Pending();if(d!=null){Choose(d);return;}if(index<current.lines.Count-1){index++;if(TryTavernTransition())return;UpdateLine();}else Complete();}
 void NextAndPlay(){int previous=index;Next();if(page=="story"&&index!=previous&&!originalPlaying&&!allPlaying&&!pausedAudio)PlayCurrent();}
 void Previous(){StopAudio();if(index>0){index--;UpdateLine();}if(page=="story")PlayCurrent();}
