 void Complete(){StopAudio();if(TavernStory.Is(current)){ShowTavernCurtain();return;}if(current.inlineQuestions){CompleteNeon();return;}if(current.questions!=null&&current.questions.Count>0&&!ShowQuiz())return;bool fresh=!save.completed.Contains(current.id);if(fresh){save.completed.Add(current.id);save.xp+=60;Persist();UpdateStats();}int trust=save.trust.ContainsKey(current.id)?save.trust[current.id]:0;string ending=trust>=2?"协作结局：你用明确的问题消除了误会，维修工作得以推进。":"谨慎结局：故障处理继续推进，但沟通仍有改善空间。";GameMessage.Show(this,ending+"\n\n"+(fresh?"章节完成 +60 XP\n":"本章已获得过通关奖励。\n")+"当前等级 Lv."+Engine.Level(save.xp)+"\n可前往章节页开启已解锁内容，或复习生词。","章节结局");}
