 void PlayCurrent(){StopAudio();StartLine(false);}
 void PlayAll(){if(current==null||current.lines==null||current.lines.Count==0)return;StopAudio();allPlaying=true;StartLine(true);}

 void StartLine(bool full){if(current.inlineQuestions&&!Attempt().review&&LineHeard())Attempt().usedReplay=true;BeginSectionTiming();PrepareAudio();if(playButton!=null&&!playButton.IsDisposed){playButton.Icon="pause";playButton.Invalidate();}var l=current.lines[index];if(audioPath!=""){long end=(long)(l.end*1000);if(full){var pending=current.decisions==null?null:current.decisions.Where(d=>d.afterLine>=index&&!save.decisions.Contains(Engine.Key(current.id,d.afterLine))).OrderBy(d=>d.afterLine).FirstOrDefault();end=(long)(current.lines[pending!=null?pending.afterLine:current.lines.Count-1].end*1000);}if(full&&current.inlineQuestions&&!Attempt().review){var q=current.questions.Where(x=>x.afterLine>=index&&!save.quizAnswers.ContainsKey(InlineKey(x))).OrderBy(x=>x.afterLine).FirstOrDefault();if(Attempt().replayAfterLine>=0)q=current.questions.First(x=>x.afterLine==Attempt().replayAfterLine);if(q!=null)end=Math.Min(end,(long)(current.lines[q.afterLine].end*1000));}if(full&&TavernStory.Is(current)&&index<=TavernStory.BattleLine&&!save.storyFlags.Contains(TavernStory.BattleFlag))end=Math.Min(end,(long)(current.lines[TavernStory.BattleLine].end*1000));if(full&&TavernStory.Is(current)&&index<TavernStory.TransferLine&&!save.storyFlags.Contains(TavernStory.TransferFlag))end=Math.Min(end,(long)(current.lines[TavernStory.TransferLine-1].end*1000));storyEndMs=end;int e=mciSendString("play storyaudio from "+SpeedTime(l.start)+" to "+(long)(end/save.storySpeed),null,0,IntPtr.Zero);if(e!=0){StopAudio();SetStatus("播放失败：请确认音频格式和分句时间点。");return;}if(current.inlineQuestions){listeningFrom=index;listeningTo=full?current.lines.FindLastIndex(x=>x.end*1000<=end+1):index;listeningChapter=current.id;}originalPlaying=true;audioTimer.Start();}else if(!String.IsNullOrWhiteSpace(current.audio)){StopAudio();GameMessage.Show(this,"内置配音未能加载，请确认完整解压了游戏文件夹，并保留音频资源。不会替换为系统语音。","配音加载失败");}else if(speech!=null){try{if(current.inlineQuestions){listeningFrom=index;listeningTo=index;listeningChapter=current.id;}SelectActorVoice(l);speech.Volume=StorySoundVolume();speech.Rate=(int)Math.Round(Math.Log(save.storySpeed,2)*5)-1;activePrompt=new Prompt(l.text);speech.SpeakAsync(activePrompt);}catch(Exception ex){StopAudio();SetStatus("配音播放失败："+ex.Message);}}else{StopAudio();SetStatus("没有可用英文语音，请导入带音频的章节。");}}
 void AudioTick(object sender,EventArgs e){if(!originalPlaying)return;var p=new StringBuilder(64);var mode=new StringBuilder(64);mciSendString("status storyaudio position",p,64,IntPtr.Zero);mciSendString("status storyaudio mode",mode,64,IntPtr.Zero);long ms;if(!long.TryParse(p.ToString(),out ms))return;ms=(long)Math.Round(ms*save.storySpeed);RecordListeningProgress(ms);if(allPlaying){int next=current.lines.FindIndex(l=>ms>=l.start*1000&&ms<l.end*1000);if(next>=0&&next!=index){index=next;UpdateLine();}}if(mode.ToString()=="stopped"||(!allPlaying&&ms>=current.lines[index].end*1000-50)){audioTimer.Stop();originalPlaying=false;if(current.inlineQuestions)RecordListening();if(allPlaying)ContinueAuto();else {if(playButton!=null&&!playButton.IsDisposed){playButton.Icon="play";playButton.Invalidate();}SetStatus("本句播放完成");}}}
 void ContinueAuto(){if(TryTavernBattle())return;ClearAnsweredReplay();if(current.inlineQuestions&&PendingInline()!=null){StopAudio();if(!ResolveInlineQuestion())return;if(index>=current.lines.Count-1){Complete();return;}index++;if(TryTavernTransition())return;UpdateLine();allPlaying=true;StartLine(true);return;}var d=Pending();if(d!=null){StopAudio();resumeAfterChoice=true;SetStatus("剧情分支：请点击“下一句 / 回应”。");return;}if(index>=current.lines.Count-1){StopAudio();Complete();return;}index++;if(TryTavernTransition())return;UpdateLine();StartLine(true);}
 void History(){StopAudio();var segment=SegmentQuestion();int first=current.inlineQuestions&&!Attempt().review&&segment!=null?SegmentFirst(segment):0;using(var f=DialogForm("对话记录",850,650)){var txt=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill,BackColor=PanelColor,ForeColor=TextColor,Font=GameTheme.Body(12)};txt.Text=String.Join("\r\n\r\n",current.lines.Where((l,i)=>i<=index&&i>=first).Select(l=>l.speaker+(englishVisible?"\r\n"+l.text:"")+(translating&&ChineseAllowed()?"\r\n"+l.translation:"")));f.Controls.Add(txt);f.ShowDialog(this);}}
 Form DialogForm(string title,int w,int h){return new PixelFrame{Text=title,Width=w,Height=h,StartPosition=FormStartPosition.CenterParent,BackColor=GameTheme.Navy,ForeColor=TextColor,Font=Font};}
 [DllImport("user32.dll")] static extern short GetAsyncKeyState(int key);
 string WordExampleTranslation(string example){if(!ChineseAllowed())return "";var line=current.lines.FirstOrDefault(l=>l.text==example);if(line!=null)return line.translation??"";return "";}
 void AddWord(string word,string example){
  if(String.IsNullOrWhiteSpace(word))return;StopAudio();var existing=save.words.FirstOrDefault(w=>w.text==word);var entry=lexicon.Find(word);string meaning=existing!=null?existing.meaning:dictionary.ContainsKey(word)?dictionary[word]:entry!=null?entry.Meaning:"";
  var f=new WordDefinitionPopup{Text="单词释义 · "+word,Width=600,Height=320};var outside=new Timer{Interval=30};var dismiss=new WordPopupDismissFilter(f);Application.AddMessageFilter(dismiss);{
   var p=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(4),BackColor=WordDefinitionPopup.Paper};f.Controls.Add(p);
   var row=new FlowLayoutPanel{AutoSize=true,WrapContents=false,Margin=new Padding(0,0,0,12)};
   var heading=new Label{Text=word,AutoSize=true,ForeColor=WordDefinitionPopup.Ink,Font=GameTheme.Latin(24)};heading.Margin=new Padding(0,8,12,0);heading.MaximumSize=new Size(350,0);row.Controls.Add(heading);
   var hear=new WordDefinitionIcon{Kind="speaker",AccessibleName="播放单词发音"};hear.Click+=(sender,e)=>SpeakWord(word);tips.SetToolTip(hear,"播放单词发音");row.Controls.Add(hear);
   var star=new WordDefinitionIcon{Kind="star",Selected=existing!=null,AccessibleName="收藏单词",Enabled=existing!=null||!String.IsNullOrWhiteSpace(meaning)};star.Click+=(sender,e)=>{ToggleRogueFavorite(new RogueEntry{word=word,meaning=meaning,example=example??""},star);};tips.SetToolTip(star,star.Selected?"已收藏到生词本":"收藏到生词本");row.Controls.Add(star);p.Controls.Add(row);
   if(entry!=null&&!String.IsNullOrWhiteSpace(entry.Phonetic)){var phonetic=new Label{Text="/"+entry.Phonetic+"/",AutoSize=true,ForeColor=WordDefinitionPopup.SoftInk,Font=GameTheme.Latin(14)};phonetic.Margin=new Padding(0,0,0,18);p.Controls.Add(phonetic);}
   var definition=new Label{Text=String.IsNullOrWhiteSpace(meaning)?"词典暂未收录此词。":meaning,AutoSize=true,ForeColor=WordDefinitionPopup.Ink,Font=GameTheme.Body(14)};definition.MaximumSize=new Size(510,0);p.Controls.Add(definition);
   bool wasDown=false;f.Shown+=(sender,e)=>{wasDown=(GetAsyncKeyState(1)&0x8000)!=0;outside.Start();};outside.Tick+=(sender,e)=>{bool down=(GetAsyncKeyState(1)&0x8000)!=0;if(down&&!wasDown&&!f.Bounds.Contains(Cursor.Position)){outside.Stop();f.Close();}wasDown=down;};f.FormClosed+=(sender,e)=>{outside.Stop();outside.Dispose();Application.RemoveMessageFilter(dismiss);f.Dispose();};
   if(wordPreviewFile!=null){f.Opacity=0;f.Show(this);Application.DoEvents();using(var bitmap=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bitmap,new Rectangle(0,0,f.Width,f.Height));bitmap.Save(wordPreviewFile);}f.Close();}else {f.Show(this);f.Location=new Point(Left+(Width-f.Width)/2,Top+(Height-f.Height)/2);}
  }
 }
 FlowLayoutPanel PageFlow(){var p=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(24)};content.Controls.Add(p);p.Controls.Add(Btn("返回主界面",ShowMain));return p;}
 void ShowChapters(){if(!developerMode){ShowTavernHub();return;}ShowStoryMap();}
 void ShowChaptersLegacy(){ClearPage();page="chapters";var p=PageFlow();p.Controls.Add(Lab("章节档案",24,Accent));p.Controls.Add(Lab("新篇每节至少两星才能解锁下一节；重玩可刷新最高星级。",11,Muted));foreach(var c in chapters){var ch=c;bool available=SectionRules.Unlocked(c,chapters,save);var panel=new FlowLayoutPanel{Width=Math.Max(750,content.Width-90),Height=135,BackColor=PanelColor,Padding=new Padding(16),FlowDirection=FlowDirection.TopDown};panel.Controls.Add(Lab(c.title+(c.inlineQuestions?(save.sectionStars.ContainsKey(c.id)?"  "+new string('★',save.sectionStars[c.id])+new string('☆',3-save.sectionStars[c.id]):"  ☆☆☆"):(save.completed.Contains(c.id)?"  ✓ 已通关":"")),16));panel.Controls.Add(Lab(c.description+" · "+c.lines.Count+" 句 · Lv."+Math.Max(1,c.unlockLevel),10,Muted));var b=Btn(available?"进入章节":"上一节需两星",()=>{current=ch;index=save.positions.ContainsKey(ch.id)?Math.Max(0,Math.Min(ch.lines.Count-1,save.positions[ch.id])):0;ShowStory();},available);b.Enabled=available;panel.Controls.Add(b);p.Controls.Add(panel);}p.Controls.Add(Lab("导入章节包后，角色姓名、英文台词、翻译、背景和音频会按章节配置显示。",10,Muted));p.Controls.Add(Btn("重玩当前章节",()=>{if(current==null)return;if(current.inlineQuestions)ResetSection();save.decisions.RemoveAll(k=>k.StartsWith(current.id+":"));save.trust[current.id]=0;index=0;save.positions[current.id]=0;Persist();ShowStory();}));p.Controls.Add(Btn("打开章节文件夹",()=>System.Diagnostics.Process.Start(Path.Combine(root,"chapters"))));}
 void ShowWords(){NavigateMenu(ShowWordsPage,"生词本",false);}
 void ShowWordsPage(){reviewWord=null;revealed=false;RenderWords();}
 void RenderWordsLegacy(){content.Controls.Clear();var p=PageFlow();int due=save.words.Count(w=>Engine.Due(w,DateTime.Now));p.Controls.Add(Lab("生词训练室",24,Accent));p.Controls.Add(Lab(save.words.Count+" 个词 · "+due+" 个待复习。先回忆词义，再翻卡检查。",11,Muted));p.Controls.Add(Btn("开始复习",()=>{reviewWord=save.words.Where(w=>Engine.Due(w,DateTime.Now)).OrderBy(w=>w.box).FirstOrDefault();revealed=false;if(reviewWord==null){SetStatus("今天的复习已完成。可以继续剧情收集新词。");}RenderWords();},true));if(reviewWord!=null){var card=new FlowLayoutPanel{Width=Math.Max(750,content.Width-90),Height=340,BackColor=PanelColor,Padding=new Padding(20),FlowDirection=FlowDirection.TopDown,WrapContents=false};card.Controls.Add(Lab(reviewWord.text,28,Gold));var ex=Lab(reviewWord.example,11,Muted);ex.MaximumSize=new Size(card.Width-50,70);card.Controls.Add(ex);card.Controls.Add(Lab(revealed?reviewWord.meaning:"先回忆，再显示词义",16));card.Controls.Add(Btn("听单词",()=>SpeakWord(reviewWord.text)));if(!revealed)card.Controls.Add(Btn("显示词义",()=>{revealed=true;RenderWords();},true));else{var actions=new FlowLayoutPanel{Width=700,Height=55};actions.Controls.Add(Btn("认识",()=>ReviewAnswer(true),true));actions.Controls.Add(Btn("忘了",()=>ReviewAnswer(false)));card.Controls.Add(actions);}p.Controls.Add(card);}if(save.words.Count==0)p.Controls.Add(Lab("生词本还是空的。回到剧情，点击任意英文单词并保存词义。",14));foreach(var w in save.words){var word=w;var row=new FlowLayoutPanel{Width=Math.Max(750,content.Width-90),AutoSize=false,Height=65,BackColor=PanelColor,Padding=new Padding(10),WrapContents=false};row.Controls.Add(Lab(w.text+"  ·  "+w.meaning+"  ·  下次 "+w.due,11));row.Controls.Add(Btn("移除",()=>{if(GameMessage.Show(this,"从生词本移除 "+word.text+"？","移除生词",MessageBoxButtons.YesNo)==DialogResult.Yes){if(reviewWord==word)reviewWord=null;save.words.Remove(word);Persist();UpdateStats();RenderWords();}}));p.Controls.Add(row);}}
 void SpeakWord(string text){StopAudio();wordDuckUntil=DateTime.UtcNow.AddMilliseconds(250);UpdateRogueAudio();string clip=Path.Combine(root,"assets","words",text+".wav");if(System.Text.RegularExpressions.Regex.IsMatch(text,"^[a-z]+$")&&File.Exists(clip)){clip=AudioVolume.Prepare(clip,WordSoundVolume(),root);int err=mciSendString("open \""+AudioDevicePath.Relative(clip)+"\" type waveaudio alias wordaudio",null,0,IntPtr.Zero);if(err==0){mciSendString("play wordaudio",null,0,IntPtr.Zero);return;}}if(speech==null){SetStatus("未找到英文语音。");return;}speech.Volume=WordSoundVolume();speech.Rate=-1;activePrompt=new Prompt(text);speech.SpeakAsync(activePrompt);}
 void ReviewAnswer(bool known){var w=reviewWord;int reward=Engine.Review(w,known,DateTime.Now);save.xp+=reward;Persist();UpdateStats();reviewWord=save.words.Where(x=>x!=w&&Engine.Due(x,DateTime.Now)).OrderBy(x=>x.box).FirstOrDefault();revealed=false;RenderWords();SetStatus(known?"已记录掌握情况 · +"+reward+" XP · 下次复习 "+w.due:"今天仍需复习这个词；稍后点击开始复习可再次练习。");}
 void Import(){StopAudio();using(var open=new OpenFileDialog{Filter="章节配置 (*.json)|*.json",Title="选择章节 JSON（音频和图片需放在同一资源文件夹）"}){if(open.ShowDialog(this)!=DialogResult.OK)return;try{string origin=Path.GetDirectoryName(open.FileName);var c=Engine.Json.Deserialize<Chapter>(File.ReadAllText(open.FileName,Encoding.UTF8));Engine.Validate(c,origin);if(chapters.Any(x=>x.id==c.id))throw new Exception("此章节 ID 已存在，请改为新的 ID 后导入。");string dest=Path.Combine(root,"chapters","import-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dest);foreach(string resource in new[]{c.audio,c.background}.Concat(c.actors==null?new string[0]:c.actors.Select(a=>a.image)).Distinct())if(!String.IsNullOrWhiteSpace(resource)){string target=Engine.SafePath(dest,resource);Directory.CreateDirectory(Path.GetDirectoryName(target));File.Copy(Engine.SafePath(origin,resource),target);}
 // Store all referenced resources beside the persisted JSON by using its relative import folder.
 if(!String.IsNullOrWhiteSpace(c.audio))c.audio=Path.GetFileName(dest)+"/"+c.audio.Replace('\\','/');if(!String.IsNullOrWhiteSpace(c.background))c.background=Path.GetFileName(dest)+"/"+c.background.Replace('\\','/');if(c.actors!=null)foreach(var actor in c.actors)actor.image=Path.GetFileName(dest)+"/"+actor.image.Replace('\\','/');string persisted=Path.Combine(root,"chapters","imported-"+Guid.NewGuid().ToString("N")+".json");File.WriteAllText(persisted,Engine.Json.Serialize(c),Encoding.UTF8);chapters.Add(c);chapters=chapters.OrderBy(x=>x.sortOrder).ThenBy(x=>x.unlockLevel).ThenBy(x=>x.id).ToList();folders[c.id]=Path.Combine(root,"chapters");ShowChapters();SetStatus("章节已导入，音频与背景已复制到游戏文件夹。");}catch(Exception ex){GameMessage.Show(this,ex.Message,"导入失败");}}}
 public void ExportPreview(string file,string mode){englishVisible=true;translating=true;Opacity=0;Show();Application.DoEvents();if(mode=="settings")ShowSettings();else if(mode=="chapters")ShowChapters();else if(mode=="words")ShowWords();else if(mode!="home"){ShowStory();if(mode=="narrow"){Width=1000;Height=660;}if(mode=="emma"){index=1;translating=false;}if(mode=="daniel")index=2;if(mode=="hidden"){englishVisible=false;translating=false;}UpdateLine();}if(stage!=null&&!stage.IsDisposed)stage.Snap();Application.DoEvents();using(var bitmap=new Bitmap(Width,Height)){DrawToBitmap(bitmap,new Rectangle(0,0,Width,Height));bitmap.Save(file);}Close();}
 static IEnumerable<Control> Descendants(Control rootControl){foreach(Control c in rootControl.Controls){yield return c;foreach(var child in Descendants(c))yield return child;}}
 static void FlowCheck(){var g=new Game();var previous=g.save;try{g.Opacity=0;g.Show();g.save=new Save();g.englishVisible=true;g.translating=false;g.ShowMain();var menu=Descendants(g).OfType<VNButton>().ToList();if(menu.First(b=>b.Text=="继续游戏").Enabled)throw new Exception("fresh continue disabled");menu.First(b=>b.Text=="开始新游戏").PerformClick();if(g.page!="story"||g.index!=0||!g.save.hasGame)throw new Exception("new game menu");g.save.xp=100;var second=g.chapters[1];g.save.lastChapter=second.id;g.save.positions[second.id]=3;g.ShowMain();Descendants(g).OfType<VNButton>().First(b=>b.Text=="继续游戏").PerformClick();if(g.current.id!=second.id||g.index!=3)throw new Exception("continue last chapter");g.englishButton.PerformClick();if(g.save.english||g.englishText.Visible||g.englishButton.Text!="英：关")throw new Exception("English toggle");g.translationButton.PerformClick();if(!g.save.chinese||g.translationButton.Text!="中：开")throw new Exception("Chinese toggle");g.ShowWords();if(g.page!="words")throw new Exception("vocabulary menu");g.ShowSettings();if(g.page!="settings")throw new Exception("settings menu");File.WriteAllText(Path.Combine(g.root,"flow-result.txt"),"PASS: fresh continue disabled; new game menu; continue last chapter and sentence; English/Chinese toggles; vocabulary and settings navigation.");}finally{g.save=previous;g.Close();}}
 [STAThread]public static void Main(string[] args){Directory.SetCurrentDirectory(AppDomain.CurrentDomain.BaseDirectory);Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);if(args.Length>0&&args[0]=="--flow-check"){try{FlowCheck();}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"flow-result.txt"),ex.ToString());Environment.ExitCode=1;}return;}if(args.Length>0&&args[0]=="--self-test"){try{SelfTest();}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-result.txt"),ex.ToString());Environment.ExitCode=1;}return;}var game=new Game();if(args.Length>1&&args[0]=="--preview"){game.ExportPreview(args[1],args.Length>2?args[2]:"story");return;}Application.Run(game);}
 static void SelfTest(){var w=new Word{text="test",due="2020-01-01"};var now=new DateTime(2026,10,2);if(Engine.Level(99)!=1||Engine.Level(100)!=2)throw new Exception("level");if(Engine.Review(w,true,now)!=10||w.due!="2026-10-03")throw new Exception("review spacing");if(Engine.Review(w,true,now)!=0)throw new Exception("duplicate reward");Engine.Review(w,false,now);if(!Engine.Due(w,now)||w.box!=0)throw new Exception("forgot");var s=new Save();s.words.Add(w);if(Engine.Json.Deserialize<Save>(Engine.Json.Serialize(s)).words.Count!=1)throw new Exception("save roundtrip");var lex=Lexicon.Load(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"assets","dictionary.tsv.gz"));if(lex.Find("computer")==null||lex.Find("stalled")==null)throw new Exception("dictionary");s.english=false;s.chinese=false;var restored=Engine.Json.Deserialize<Save>(Engine.Json.Serialize(s));if(restored.english||restored.chinese)throw new Exception("visibility save");s.xp=300;s.positions["old"]=9;s.lastChapter="old";Engine.StartNewStory(s,"first");if(s.xp!=0||s.positions.Count!=1||s.positions["first"]!=0||s.words.Count!=1||s.english||s.chinese||!s.hasGame||s.lastChapter!="first")throw new Exception("new game preserves vocabulary and settings");bool blocked=false;try{Engine.SafePath(AppDomain.CurrentDomain.BaseDirectory,"../outside.mp3");}catch{blocked=true;}if(!blocked)throw new Exception("path traversal");var c=new Chapter{id="t",title="t",lines=new List<Line>{new Line{text="Hello"}}};Engine.Validate(c,AppDomain.CurrentDomain.BaseDirectory);c.lines[0].text="";blocked=false;try{Engine.Validate(c,AppDomain.CurrentDomain.BaseDirectory);}catch{blocked=true;}if(!blocked)throw new Exception("invalid import");foreach(string f in Directory.GetFiles(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"chapters"),"*.json")){var chapter=Engine.Json.Deserialize<Chapter>(File.ReadAllText(f,Encoding.UTF8));Engine.Validate(chapter,Path.GetDirectoryName(f));foreach(var line in chapter.lines)foreach(Match token in Regex.Matches(line.text,"[A-Za-z]+(?:['’][A-Za-z]+)?"))if(!new[]{"xingyao","lu","chuan","iserya","aelia","cet"}.Contains(Normalize(token.Value))&&lex.Find(Normalize(token.Value))==null)throw new Exception("missing definition: "+token.Value);if(!String.IsNullOrWhiteSpace(chapter.audio)){string ap=Engine.SafePath(Path.GetDirectoryName(f),chapter.audio);string scaled=AudioVolume.Prepare(ap,50,AppDomain.CurrentDomain.BaseDirectory);if(scaled==ap||new FileInfo(scaled).Length!=new FileInfo(ap).Length)throw new Exception("PCM volume and timing preservation");if(mciSendString("open \""+AudioDevicePath.Relative(ap)+"\" type waveaudio alias testaudio",null,0,IntPtr.Zero)!=0)throw new Exception("audio open");mciSendString("set testaudio time format milliseconds",null,0,IntPtr.Zero);var length=new StringBuilder(64);mciSendString("status testaudio length",length,64,IntPtr.Zero);if(long.Parse(length.ToString())<chapter.lines.Last().end*1000)throw new Exception("audio duration");mciSendString("close testaudio",null,0,IntPtr.Zero);}}File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-result.txt"),"PASS: level progression; review scheduling; reward deduplication; save roundtrip; import validation; relative resource paths; all demo definitions; visibility persistence; new game reset; PCM volume; audio timings.");}
